#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common Polybench definitions (NI, NJ, NK, NL, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions for 2mm
#include "2mm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A, B, C, D in the same way as the original C version.
 *
 * C layout:
 *   A[ni][nk] -> Buffer A(k, i)  with shape (nk, ni)
 *   B[nk][nj] -> Buffer B(j, k)  with shape (nj, nk)
 *   C[nj][nl] -> Buffer C(l, j)  with shape (nl, nj)
 *   D[ni][nl] -> Buffer D(l, i)  with shape (nl, ni)
 */
static void init_array(int ni, int nj, int nk, int nl,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> D) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j"), k("k"), l("l");
    Func init_A("init_A"), init_B("init_B"), init_C("init_C"), init_D("init_D");

    // A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
    // A is stored as A(k, i) with shape (nk, ni)
    init_A(k, i) = cast<num_t>(((i * k + 1) % ni)) / cast<num_t>(ni);

    // B[i][j] = (DATA_TYPE) (i*(j+1) % nj) / nj;
    // B is stored as B(j, k) with shape (nj, nk)
    init_B(j, k) = cast<num_t>(((k * (j + 1)) % nj)) / cast<num_t>(nj);

    // C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
    // C is stored as C(l, j) with shape (nl, nj)
    init_C(l, j) = cast<num_t>(((j * (l + 3) + 1) % nl)) / cast<num_t>(nl);

    // D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
    // D is stored as D(l, i) with shape (nl, ni)
    init_D(l, i) = cast<num_t>(((i * (l + 2)) % nk)) / cast<num_t>(nk);

    // Simple CPU schedules for initialization: parallelize over the slow
    // dimension and vectorize over the contiguous dimension. This keeps
    // initialization cheap even for large problem sizes.
    Target init_target = get_jit_target_from_environment();
    int init_vec = init_target.natural_vector_size(type_of<num_t>());
    if (init_vec <= 0) init_vec = 1;

    init_A
        .compute_root()
        .parallel(i)
        .vectorize(k, init_vec);

    init_B
        .compute_root()
        .parallel(k)
        .vectorize(j, init_vec);

    init_C
        .compute_root()
        .parallel(j)
        .vectorize(l, init_vec);

    init_D
        .compute_root()
        .parallel(i)
        .vectorize(l, init_vec);

    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;

    // Scalar parameters
    num_t alpha;
    num_t beta;

    // Buffers corresponding to the C arrays:
    //
    // A[ni][nk] -> A(k, i)
    // B[nk][nj] -> B(j, k)
    // C[nj][nl] -> C(l, j)
    // D[ni][nl] -> D(l, i)
    // tmp[ni][nj] -> tmp(j, i)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nl, nj);
    Halide::Buffer<num_t, 2> D(nl, ni);
    Halide::Buffer<num_t, 2> tmp(nj, ni);

    // ImageParams to pass the buffers into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    // Initialize data (equivalent to init_array in the C version)
    init_array(ni, nj, nk, nl, &alpha, &beta, A, B, C, D);

    // Bind buffers to ImageParams
    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // ------------------------------------------------------------------------
    // Halide definition of the 2mm kernel:
    //
    // Original C:
    //   /* D := alpha*A*B*C + beta*D */
    //   for (i)
    //     for (j)
    //       tmp[i][j] = 0;
    //       for (k)
    //         tmp[i][j] += alpha * A[i][k] * B[k][j];
    //
    //   for (i)
    //     for (j)
    //       D[i][j] *= beta;
    //       for (k)
    //         D[i][j] += tmp[i][k] * C[k][j];
    //
    // Mapping to Halide coordinates:
    //   i -> row index  (second dimension)
    //   j -> column index for tmp and D (first dimension)
    //   k -> reduction indices (nk for tmp, nj for D)
    //
    // Buffers:
    //   tmp(j, i) corresponds to tmp[i][j]
    //   A_param(k, i) corresponds to A[i][k]
    //   B_param(j, k) corresponds to B[k][j]
    //   C_param(l, j) corresponds to C[j][l]
    //   D_param(l, i) corresponds to D[i][l]
    // ------------------------------------------------------------------------

    Var i("i"), j("j"), l("l");
    RDom k_AB(0, A_param.dim(0).extent(), "k_AB");   // reduction over nk
    RDom k_DC(0, C_param.dim(1).extent(), "k_DC");   // reduction over nj

    Func tmp_func("tmp");
    Func D_func("D");

    // tmp[i][j] accumulation: tmp(j, i)
    tmp_func(j, i) = cast<num_t>(0);
    tmp_func(j, i) += Expr(alpha) * A_param(k_AB, i) * B_param(j, k_AB);

    // D[i][l] update: D(l, i)
    D_func(l, i) = Expr(beta) * D_param(l, i);
    D_func(l, i) += tmp_func(k_DC, i) * C_param(l, k_DC);

    // ------------------------------------------------------------------------
    // Optimized scheduling
    //
    // Goals:
    //   * Keep inner loops on the contiguous (x) dimension for good
    //     memory bandwidth and vectorization.
    //   * Parallelize across rows (i) to exploit many cores.
    //   * Compute each row of tmp on-the-fly just before it is used
    //     to update the corresponding row of D, to improve cache
    //     locality and avoid storing the full tmp matrix at once.
    //
    // Layout recap:
    //   A(k, i): k is contiguous
    //   B(j, k): j is contiguous
    //   C(l, j): l is contiguous
    //   D(l, i): l is contiguous
    //   tmp(j, i): j is contiguous
    //
    // For tmp:
    //   We reorder the reduction so that the inner loop is j, not k:
    //     for i
    //       for k
    //         for j   (vectorized)
    //           tmp[j,i] += alpha * A[k,i] * B[j,k]
    //   This gives contiguous access to both A (over k) and B (over j).
    //
    // For D:
    //   We reorder the reduction so that the inner loop is l:
    //     for i (parallel)
    //       for l_outer
    //         for k
    //           for l_inner (vectorized)
    //             D[l,i] += tmp[k,i] * C[l,k]
    //   This gives contiguous, vectorized access to C and D along l.
    //
    //   tmp is scheduled compute_at(D_func, i), so for each row i of D
    //   we first build the entire row tmp[i][:] once, then reuse it
    //   across all l for that row. This mimics a tiled row-wise
    //   computation and greatly improves data locality versus computing
    //   all of tmp as a separate pass.
    // ------------------------------------------------------------------------

    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width <= 0) vec_width = 1;

    // Schedule D_func (output)
    Var l_outer("l_outer"), l_inner("l_inner");

    D_func
        .compute_root()
        // Split the contiguous l-dimension for vectorization.
        .split(l, l_outer, l_inner, vec_width)
        // Make i the outermost (row loop), then l_outer (tiles),
        // then l_inner (vectorized lane).
        .reorder(l_inner, l_outer, i)
        // Parallelize across rows of D.
        .parallel(i)
        // Vectorize across contiguous l_inner.
        .vectorize(l_inner);

    // Reduction update: D(l, i) += tmp(k_DC, i) * C(l, k_DC)
    // We want:
    //   for i (parallel)
    //     for l_outer
    //       for k_DC
    //         for l_inner (vectorized)
    //           D[...] += ...
    D_func.update()
        .reorder(l_inner, k_DC, l_outer, i)
        .vectorize(l_inner);

    // Schedule tmp_func (intermediate A*B)
    tmp_func
        // Compute a full row tmp(i, :) just before using it to
        // update row i of D. Because D_func is parallel over i,
        // each worker thread computes its own row of tmp.
        .compute_at(D_func, i)
        // Pure initialization tmp(j,i) = 0; j is contiguous.
        .vectorize(j, vec_width);

    // Reduction update: tmp(j, i) += alpha * A(k_AB, i) * B(j, k_AB)
    // We want:
    //   for i
    //     for k_AB
    //       for j (vectorized)
    //         tmp[j,i] += ...
    tmp_func.update()
        .reorder(j, k_AB, i)
        .vectorize(j, vec_width);

    // ------------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------------

    D_func.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: result is written into D
    D_func.realize(D);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix, similar to print_array in C.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // D(ii, jj) in C is D(l = jj, i = ii) in Halide
                std::cerr << D(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
