    // D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
    // D is stored as D(l, i) with shape (nl, ni)
    init_D(l, i) = cast<num_t>(((i * (l + 2)) % nk)) / cast<int>(nk);

    // ----------------------------------------------------------------------
    // Scheduling for initialization
    //
    // These initializations are embarrassingly parallel and have simple
    // expressions. We:
    //   - Make the fastest‑varying dimension (dim 0) the inner loop.
    //   - Vectorize along dim 0 for better SIMD utilization.
    //   - Parallelize along the outer dimension.
    //
    // This keeps the memory access pattern contiguous in innermost loops and
    // uses all CPU cores, while keeping the code very simple.
    // ----------------------------------------------------------------------
    const int init_vec_width = 8;  // Tunable; works well on AVX-class CPUs.

    init_A
        .compute_root()
        .reorder(k, i)              // inner: k (dim 0), outer: i (dim 1)
        .vectorize(k, init_vec_width)
        .parallel(i);

    init_B
        .compute_root()
        .reorder(j, k)              // inner: j (dim 0), outer: k (dim 1)
        .vectorize(j, init_vec_width)
        .parallel(k);

    init_C
        .compute_root()
        .reorder(l, j)              // inner: l (dim 0), outer: j (dim 1)
        .vectorize(l, init_vec_width)
        .parallel(j);

