int main(int argc, char *argv[]) {
    // Problem sizes
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;

    // Scalar parameters
    num_t alpha;
    num_t beta;

    // Buffers corresponding to the C arrays:
    //
    // A[ni][nk] -> A(k, i)
    // B[nk][nj] -> B(j, k)
    // C[nj][nl] -> C(l, j)
    // D[ni][nl] -> D(l, i)
    // tmp[ni][nj] -> tmp(j, i)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nl, nj);
    Halide::Buffer<num_t, 2> D(nl, ni);
    Halide::Buffer<num_t, 2> tmp(nj, ni);  // allocated for completeness; not used directly

    // ImageParams to pass the buffers into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    // Initialize data (equivalent to init_array in the C version)
    init_array(ni, nj, nk, nl, &alpha, &beta, A, B, C, D);

    // Bind buffers to ImageParams
    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // ------------------------------------------------------------------------
    // Halide definition of the 2mm kernel:
    //
    // Original C:
    //   /* D := alpha*A*B*C + beta*D */
    //   for (i)
    //     for (j) {
    //       tmp[i][j] = 0;
    //       for (k)
    //         tmp[i][j] += alpha * A[i][k] * B[k][j];
    //     }
    //
    //   for (i)
    //     for (j) {
    //       D[i][j] *= beta;
    //       for (k)
    //         D[i][j] += tmp[i][k] * C[k][j];
    //     }
    //
    // Mapping to Halide coordinates:
    //   i -> row index  (second dimension)
    //   j -> column index for tmp and (second) GEMM (first dimension)
    //   k -> reduction indices (nk for tmp, nj for D)
    //
    // Buffers:
    //   tmp(j, i)      corresponds to tmp[i][j]
    //   A_param(k, i)  corresponds to A[i][k]
    //   B_param(j, k)  corresponds to B[k][j]
    //   C_param(l, j)  corresponds to C[j][l]
    //   D_param(l, i)  corresponds to D[i][l]
    // ------------------------------------------------------------------------

    Var i("i"), j("j"), l("l");
    RDom k_AB(0, A_param.dim(0).extent(), "k_AB");   // reduction over nk
    RDom k_DC(0, C_param.dim(1).extent(), "k_DC");   // reduction over nj

    Func tmp_func("tmp");
    Func D_func("D");

    // Use Expr wrappers for the scalar coefficients. They are constants at JIT time,
    // so Halide will fold them efficiently.
    Expr alpha_expr = Expr(alpha);
    Expr beta_expr  = Expr(beta);

    // tmp[i][j] accumulation: tmp(j, i)
    tmp_func(j, i) = cast<num_t>(0);
    tmp_func(j, i) += alpha_expr * A_param(k_AB, i) * B_param(j, k_AB);

    // D[i][l] update: D(l, i)
    D_func(l, i) = beta_expr * D_param(l, i);
    D_func(l, i) += tmp_func(k_DC, i) * C_param(l, k_DC);

    // ------------------------------------------------------------------------
    // Scheduling
    //
    // Goals:
    //  - Preserve the original accumulation order over k to keep FP
    //    behavior as close as possible to the C version.
    //  - Make the fastest-varying Halide dimension (dim 0) the innermost
    //    loop to maximize cache efficiency and enable vectorization.
    //  - Parallelize over the independent row dimension (i) for both
    //    tmp and D to exploit all CPU cores.
    //
    // We avoid advanced storage folding / compute_at tricks here to keep
    // the schedule simple, robust, and easy to reason about, while still
    // giving good performance on a multi-core CPU.
    // ------------------------------------------------------------------------

    const int vec_width = 8;  // Tunable SIMD width; 8 works well for AVX on float.

    // ---- tmp_func schedule --------------------------------------------------
    //
    // Default loop nest for tmp (conceptually):
    //   for i
    //     for j
    //       tmp(j, i) = 0       // pure definition
    //   for i
    //     for j
    //       for k_AB
    //         tmp(j, i) += ...
    //
    // We:
    //   - Make j (dim 0) the innermost loop for contiguous access.
    //   - Vectorize over j.
    //   - Parallelize over i.
    //
    tmp_func
        .compute_root()
        .reorder(j, i)                // inner: j, outer: i
        .vectorize(j, vec_width)
        .parallel(i);

    tmp_func.update()
        .reorder(k_AB, j, i)          // inner: k_AB, then j, outer: i
        .vectorize(j, vec_width)
        .parallel(i);
    // Note: we only parallelize over i (rows). Each (i,j) has its own
    // reduction over k_AB, so there are no cross-thread data races.

    // ---- D_func schedule ----------------------------------------------------
    //
    // Default loop nest for D (conceptually):
    //   for i
    //     for l
    //       D(l, i) = beta * D_orig(l, i)
    //   for i
    //     for l
    //       for k_DC
    //         D(l, i) += tmp(i, k_DC) * C(l, k_DC)
    //
    // We:
    //   - Make l (dim 0) the innermost loop; D and C are contiguous in l.
    //   - Vectorize over l.
    //   - Parallelize over i (rows), the same as for tmp.
    //
    D_func
        .compute_root()
        .reorder(l, i)                // inner: l, outer: i
        .vectorize(l, vec_width)
        .parallel(i);

    D_func.update()
        .reorder(k_DC, l, i)          // inner: k_DC, then l, outer: i
        .vectorize(l, vec_width)
        .parallel(i);
    // Again, each (l,i) has its own reduction over k_DC, and we only
    // parallelize outer loops, so there are no reduction races.

    // ------------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------------
    Target target = get_host_target();
    D_func.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: result is written into D
    D_func.realize(D);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix, similar to print_array in C.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // D(ii, jj) in C is D(l = jj, i = ii) in Halide
                std::cerr << D(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
