int main(int argc, char *argv[]) {
    // Problem sizes
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;

    // Scalar parameters
    num_t alpha;
    num_t beta;

    // Buffers corresponding to the C arrays:
    //
    // A[ni][nk] -> A(k, i)
    // B[nk][nj] -> B(j, k)
    // C[nj][nl] -> C(l, j)
    // D[ni][nl] -> D(l, i)
    // tmp[ni][nj] -> tmp(j, i)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nl, nj);
    Halide::Buffer<num_t, 2> D(nl, ni);
    Halide::Buffer<num_t, 2> tmp(nj, ni);  // allocated but used only internally by Halide

    // ImageParams to pass the buffers into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    // Initialize data (equivalent to init_array in the C version)
    init_array(ni, nj, nk, nl, &alpha, &beta, A, B, C, D);

    // For correct semantics we must read the "old" D when computing
    //    D := alpha*A*B*C + beta*D
    // so we bind D_param to a *copy* of D, and realize the result back
    // into D. This avoids aliasing input and output.
    Halide::Buffer<num_t, 2> D_in = D.copy();

    // Bind buffers to ImageParams
    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D_in);

    // ------------------------------------------------------------------------
    // Halide definition of the 2mm kernel:
    //
    // Original C:
    //   /* D := alpha*A*B*C + beta*D */
    //   for (i)
    //     for (j)
    //       tmp[i][j] = 0;
    //       for (k)
    //         tmp[i][j] += alpha * A[i][k] * B[k][j];
    //
    //   for (i)
    //     for (j)
    //       D[i][j] *= beta;
    //       for (k)
    //         D[i][j] += tmp[i][k] * C[k][j];
    //
    // Mapping to Halide coordinates:
    //   i -> row index  (second dimension)
    //   j -> column index for tmp and D (first dimension)
    //   k -> reduction indices (nk for tmp, nj for D)
    //
    // Buffers:
    //   tmp(j, i) corresponds to tmp[i][j]
    //   A_param(k, i) corresponds to A[i][k]
    //   B_param(j, k) corresponds to B[k][j]
    //   C_param(l, j) corresponds to C[j][l]
    //   D_param(l, i) corresponds to D[i][l] (original input)
    //   Final D(l, i) buffer holds the updated D[i][l]
    // ------------------------------------------------------------------------

    Var i("i"), j("j"), l("l");
    RDom k_AB(0, A_param.dim(0).extent(), "k_AB");   // reduction over nk
    RDom k_DC(0, C_param.dim(1).extent(), "k_DC");   // reduction over nj

    Func tmp_func("tmp");
    Func D_func("D");

    // tmp[i][j] accumulation: tmp(j, i)
    tmp_func(j, i) = cast<num_t>(0);
    tmp_func(j, i) += Expr(alpha) * A_param(k_AB, i) * B_param(j, k_AB);

    // D[i][l] update: D(l, i)
    D_func(l, i) = Expr(beta) * D_param(l, i);
    D_func(l, i) += tmp_func(k_DC, i) * C_param(l, k_DC);

    // ------------------------------------------------------------------------
    // Scheduling
    //
    // Goals:
    //  - Preserve original semantics.
    //  - Exploit cache locality via tiling of (i,j) and (i,l) spaces.
    //  - Vectorize along the unit-stride (x) dimensions: j for tmp, l for D.
    //  - Parallelize across blocks of rows (i dimension), which are independent.
    //
    // We keep tmp and D as two separate matrix-multiply-like stages, but
    // schedule each with blocking and parallelism. This greatly improves
    // locality and computational efficiency compared to the naïve schedule.
    // ------------------------------------------------------------------------

    Target target = get_jit_target_from_environment();
    const int vec_width = natural_vector_size<num_t>(target);

    // Tunable tile sizes (can be changed to tune for a given machine/cache)
    const int TILE_I = 32;  // tile size along i (rows)
    const int TILE_J = 64;  // tile size along j for tmp
    const int TILE_L = 64;  // tile size along l for D

    // -------------------------
    // Schedule for tmp_func
    // -------------------------
    Var io("io"), jo("jo"), ii("ii"), ji("ji");

    // Pure definition: compute tmp in tiles of (j,i).
    tmp_func
        .compute_root()
        // tile over j (fast dim) and i (slow dim)
        .tile(j, i, jo, io, ji, ii, TILE_J, TILE_I)
        // innermost: ji (vectorized along j), then ii, then jo, then io
        .reorder(ji, ii, jo, io);

    if (vec_width > 1) {
        tmp_func.vectorize(ji, vec_width);
    }
    // Parallelize across blocks of rows
    tmp_func.parallel(io);

    // Update definition: same tiling structure as pure step
    {
        auto tmp_update = tmp_func.update();
        tmp_update
            .tile(j, i, jo, io, ji, ii, TILE_J, TILE_I)
            // reduction loop k_AB is innermost over tiles in (i,j):
            // order: ji (vec), ii, k_AB, jo, io
            .reorder(ji, ii, k_AB, jo, io);

        if (vec_width > 1) {
            tmp_update.vectorize(ji, vec_width);
        }
        tmp_update.parallel(io);
    }

    // -------------------------
    // Schedule for D_func
    // -------------------------
    Var lo("lo"), li("li");

    // Pure definition: D(l, i) -> tile over (l,i)
    D_func
        .compute_root()
        .tile(l, i, lo, io, li, ii, TILE_L, TILE_I)
        // innermost: li (vectorized along l), then ii, then lo, then io
        .reorder(li, ii, lo, io);

    if (vec_width > 1) {
        D_func.vectorize(li, vec_width);
    }
    // Parallelize across blocks of rows (io)
    D_func.parallel(io);

    // Update definition: same tiling; reduction in k_DC inside tile
    {
        auto D_update = D_func.update();
        D_update
            .tile(l, i, lo, io, li, ii, TILE_L, TILE_I)
            // order: li (vec), ii, k_DC, lo, io
            .reorder(li, ii, k_DC, lo, io);

        if (vec_width > 1) {
            D_update.vectorize(li, vec_width);
        }
        D_update.parallel(io);
    }

    // ------------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------------

    D_func.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: result is written into D
    D_func.realize(D);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix, similar to print_array in C.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // D(ii, jj) in C is D(l = jj, i = ii) in Halide
                std::cerr << D(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
