    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    // Initialize data (equivalent to init_array in the C version)
    init_array(ni, nj, nk, nl, &alpha, &beta, A, B, C, D);

    // Bind buffers to ImageParams
    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // ------------------------------------------------------------------------
    // Halide definition of the 2mm kernel:
    //
    // Original C:
    //   /* D := alpha*A*B*C + beta*D */
    //   for (i)
    //     for (j)
    //       tmp[i][j] = 0;
    //       for (k)
    //         tmp[i][j] += alpha * A[i][k] * B[k][j];
    //
    //   for (i)
    //     for (j)
    //       D[i][j] *= beta;
    //       for (k)
    //         D[i][j] += tmp[i][k] * C[k][j];
    //
    // Mapping to Halide coordinates:
    //   i -> row index  (second dimension)
    //   j -> column index for tmp and D (first dimension)
    //   k -> reduction indices (nk for tmp, nj for D)
    //
    // Buffers:
    //   tmp(j, i) corresponds to tmp[i][j]
    //   A_param(k, i) corresponds to A[i][k]
    //   B_param(j, k) corresponds to B[k][j]
    //   C_param(l, j) corresponds to C[j][l]
    //   D_param(l, i) corresponds to D[i][l]
    // ------------------------------------------------------------------------

    Var i("i"), j("j"), l("l");
    RDom k_AB(0, A_param.dim(0).extent(), "k_AB");   // reduction over nk
    RDom k_DC(0, C_param.dim(1).extent(), "k_DC");   // reduction over nj

    Func tmp_func("tmp");
    Func D_func("D");

    // tmp[i][j] accumulation: tmp(j, i)
    tmp_func(j, i) = cast<num_t>(0);
    tmp_func(j, i) += Expr(alpha) * A_param(k_AB, i) * B_param(j, k_AB);

    // D[i][l] update: D(l, i)
    // D is updated in-place mathematically: D = beta*D + tmp*C
    D_func(l, i) = Expr(beta) * D_param(l, i);
    D_func(l, i) += tmp_func(k_DC, i) * C_param(l, k_DC);

    // ------------------------------------------------------------------------
    // Scheduling
    //
    // Goals:
    //  - Good cache locality for both matrix multiplications.
    //  - Avoid materializing the full tmp(ni x nj) when not needed.
    //  - Vectorize along memory-contiguous dimensions.
    //  - Parallelize across the outer "row" dimension i.
    //
    // Layout recap:
    //   A(k, i) : k contiguous
    //   B(j, k) : j contiguous
    //   C(l, j) : l contiguous
    //   D(l, i) : l contiguous
    //   tmp(j,i): j contiguous
    //
    // High-level execution we target:
    //
    //   for i (parallel):
    //     compute tmp(j, i) for all j
    //       (inner loop over j, vectorized; reduction over k_AB)
    //     scale D(l, i) by beta
    //     for each reduction index k_DC:
    //       update D(l, i) across l (vectorized), using tmp(k_DC, i)
    //
    // This keeps data for a single row i in cache, uses tmp only per-row,
    // and streams D and C in contiguous order across l.
    // ------------------------------------------------------------------------

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Final output at root: parallel over rows (i), vectorize over columns (l).
    D_func.compute_root();

    // Make 'l' (column index in D) innermost for contiguous writes.
    D_func.reorder(l, i);
    D_func.vectorize(l, vec_width);
    D_func.parallel(i);

    // Update step:
    //   for i (parallel)
    //     for k_DC
    //       for l (vectorized, contiguous)
    //
    // This: streams C(l, k_DC) and D(l, i) in memory order.
    D_func.update()
        .reorder(l, k_DC, i)        // i outer, k_DC middle, l inner
        .vectorize(l, vec_width)
        .parallel(i);

    // Compute tmp per row 'i' inside the D pipeline.
    // This avoids storing the entire tmp(ni x nj) matrix at once:
    // we only need a 1D slice tmp(j, i) for the current i.
    tmp_func.compute_at(D_func, i);

    // Pure tmp initialization: j is contiguous, so keep it innermost.
    tmp_func.reorder(j, i);
    tmp_func.vectorize(j, vec_width);

    // Update step for tmp:
    // Reorder so that 'j' is innermost and vectorizable; for each (i,k_AB)
    // we sweep across all columns j using contiguous accesses to tmp and B.
    tmp_func.update()
        .reorder(j, k_AB, i)   // i outer, k_AB middle, j inner
        .vectorize(j, vec_width);

    // ------------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------------

    D_func.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: result is written into D
    D_func.realize(D);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix, similar to print_array in C.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // D(ii, jj) in C is D(l = jj, i = ii) in Halide
                std::cerr << D(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
